class Fancy {
  private static final long MOD = 1_000_000_007L;
  private final java.util.List<Long> values = new java.util.ArrayList<>();
  private long mul = 1, add = 0;

  public void append(int val) {
    values.add((val - add + MOD) % MOD * inv(mul) % MOD);
  }

  public void addAll(int inc) {
    add = (add + inc) % MOD;
  }

  public void multAll(int m) {
    mul = mul * m % MOD;
    add = add * m % MOD;
  }

  public int getIndex(int idx) {
    if (idx < 0 || idx >= values.size()) return -1;
    return (int) ((values.get(idx) * mul + add) % MOD);
  }

  private long inv(long x) {
    return pow(x, MOD - 2);
  }

  private long pow(long x, long e) {
    long result = 1;
    while (e > 0) {
      if ((e & 1) != 0) result = result * x % MOD;
      x = x * x % MOD;
      e >>= 1;
    }
    return result;
  }
}
